  const g = c.getContext('2d'), t0 = performance.now(), HIT = .95, END = kind === 'fail' ? 3 : 3.2, P = [], col = kind === 'fail' ? '#ff4a3a' : kind === 'keep' ? '#6ab4ff' : kind === 'reroll' ? '#c9a8ff' : kind === 'double' ? '#ffffff' : '#ffd166';
