      if (kind === 'double') { const gr = g.createLinearGradient(-160, 0, 160, 0); for (let i = 0; i <= 6; i++) gr.addColorStop(i / 6, `hsl(${(i * 60 + t * 240) % 360},100%,65%)`); g.fillStyle = gr; } else g.fillStyle = col; g.fillText(text, 0, 0);
